// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;

    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(address caller, address recipient, uint96 amount) public {
        uint256 bal = bound(amount, 1, 1 ether);

        vm.deal(address(this), bal);
        (bool sent, ) = address(c).call{value: bal}("");
        require(sent, "funding failed");

        vm.assume(caller != address(0));
        vm.assume(recipient != address(0));

        bool ok;
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        if (caller != address(this)) {
            assertTrue(address(c).balance == bal);
        } else {
            assertTrue(address(c).balance == 0);
        }
    }
}
